import{_ as a,o as t,c as i,a0 as s}from"./chunks/framework.CzVS_xMp.js";const n="/ai-data-center-systems/assets/01-locality-aware-serving-pipeline.Dg2KIS2i.svg",r="/ai-data-center-systems/assets/02-pd-disaggregation-request-flow.CM6B7YE8.svg",o="/ai-data-center-systems/assets/03-production-adoption-ladder.t9Fv2Vzu.svg",m=JSON.parse('{"title":"SGLang in 2026: Engineering a Production-Grade LLM Serving Stack","description":"","frontmatter":{},"headers":[],"relativePath":"inference/sglang-production-practices/index.md","filePath":"inference/sglang-production-practices/index.md","lastUpdated":1788490169000}'),l={name:"inference/sglang-production-practices/index.md"};function d(p,e,c,h,u,g){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="sglang-in-2026-engineering-a-production-grade-llm-serving-stack" tabindex="-1">SGLang in 2026: Engineering a Production-Grade LLM Serving Stack <a class="header-anchor" href="#sglang-in-2026-engineering-a-production-grade-llm-serving-stack" aria-label="Permalink to &quot;SGLang in 2026: Engineering a Production-Grade LLM Serving Stack&quot;">​</a></h1><blockquote><p>From RadixAttention to cache-aware routing, hierarchical KV storage, speculative decoding, prefill-decode disaggregation, and model-aware parallelism</p></blockquote><p><strong>Version scope:</strong> SGLang v0.5.18, released August 22, 2026. Commands and defaults should be revalidated when upgrading.</p><p>SGLang is often introduced as a fast inference engine. That description is correct, but no longer sufficient.</p><p>Its original contribution was a co-design of a structured-generation frontend and an inference runtime. The runtime introduced <strong>RadixAttention</strong> for automatic KV-cache reuse and compressed finite-state machines for structured decoding. Since then, the project has expanded into a broader serving stack: an overlapped scheduler, cache-aware routing, speculative decoding, hierarchical KV caching, prefill-decode disaggregation, expert parallelism, data-parallel attention, decode context parallelism, and a Rust-based model gateway.</p><p>Lianmin Zheng&#39;s presentation, <em>Efficient LLM Inference with SGLang</em>, is a strong architectural entry point because it captures the transition from single-engine optimization to distributed inference design. Its main themes—zero-overhead scheduling, speculative decoding, prefill-decode disaggregation, and large-scale expert parallelism—remain central. The 2026 production picture, however, adds another layer: <strong>the serving system must coordinate KV locality, request routing, phase-specific execution, model-specific parallelism, and operational feedback as one system</strong>.</p><p>The useful question is therefore not:</p><blockquote><p>Is SGLang faster than another engine?</p></blockquote><p>It is:</p><blockquote><p>Which SGLang topology produces the best SLO-compliant goodput for this model, workload, hardware, and failure budget?</p></blockquote><p>This article develops a practical answer.</p><h2 id="reading-map" tabindex="-1">Reading map <a class="header-anchor" href="#reading-map" aria-label="Permalink to &quot;Reading map&quot;">​</a></h2><ol><li><a href="#1-start-with-the-latency-decomposition-not-a-leaderboard">Latency decomposition and production metrics</a></li><li><a href="#2-a-modern-sglang-deployment-is-a-locality-aware-pipeline">Locality-aware serving architecture</a></li><li><a href="#3-radixattention-makes-prompt-structure-an-infrastructure-concern">RadixAttention and prompt canonicalization</a></li><li><a href="#4-build-a-boring-baseline-before-enabling-advanced-features">Reproducible single-node baseline</a></li><li><a href="#5-benchmark-the-workload-you-actually-operate">Workload-representative benchmarking</a></li><li><a href="#6-choose-parallelism-from-the-model-architecture-outward">Model-aware parallelism</a></li><li><a href="#7-speculative-decoding-is-an-acceptance-rate-optimization">Speculative decoding</a></li><li><a href="#8-hicache-extends-reuse-beyond-hbm-but-capacity-is-not-locality">HiCache and hierarchical KV storage</a></li><li><a href="#9-pd-disaggregation-is-phase-isolation-not-a-free-speedup">Prefill-decode disaggregation</a></li><li><a href="#10-the-model-gateway-is-part-of-the-inference-runtime">Model Gateway routing and admission</a></li><li><a href="#11-use-breakable-cuda-graph-as-a-targeted-escape-hatch">Breakable CUDA Graph</a></li><li><a href="#12-observability-should-explain-the-bottleneck-not-only-report-latency">Observability</a></li><li><a href="#13-upgrade-and-startup-behavior-are-part-of-reliability">Upgrade and startup reliability</a></li><li><a href="#14-a-practical-adoption-ladder">Adoption ladder</a></li><li><a href="#15-production-checklist">Production checklist</a></li><li><a href="#conclusion">Conclusion</a></li><li><a href="#references">References</a></li></ol><h3 id="related-foundations" tabindex="-1">Related foundations <a class="header-anchor" href="#related-foundations" aria-label="Permalink to &quot;Related foundations&quot;">​</a></h3><ul><li>[Transformer inference and the KV cache](../efficient-llm-inference-systems/week03/</li><li>[Speculative decoding](../efficient-llm-inference-systems/week05/</li><li>[Inference model architecture profiles](../models/</li></ul><hr><h2 id="_1-start-with-the-latency-decomposition-not-a-leaderboard" tabindex="-1">1. Start with the latency decomposition, not a leaderboard <a class="header-anchor" href="#_1-start-with-the-latency-decomposition-not-a-leaderboard" aria-label="Permalink to &quot;1. Start with the latency decomposition, not a leaderboard&quot;">​</a></h2><p>An online generation request can be approximated as:</p><p>[ T_{e2e} \\approx T_{queue} + T_{prefill} + (N_{out}-1),T_{pot} + T_{network} ]</p><p>where:</p><ul><li>(T_{queue}) is admission and scheduling delay,</li><li>(T_{prefill}) determines most of time to first token,</li><li>(T_{pot}) is time per output token after the first token,</li><li>(N_{out}) is output length,</li><li>(T_{network}) includes client transport and, in disaggregated systems, internal KV transfer.</li></ul><p>This decomposition matters because the two transformer inference phases behave differently:</p><ul><li><strong>Prefill</strong> processes many prompt tokens together and is usually compute-intensive.</li><li><strong>Decode</strong> produces a small number of tokens per sequence per step and is commonly constrained by memory traffic, KV-cache capacity, collective communication, or host-side launch overhead.</li></ul><p>A useful first-order estimate for a conventional attention model&#39;s per-sequence KV-cache footprint is:</p><p>[ KV_{bytes} \\approx 2 \\times L \\times S \\times H_{kv} \\times D_h \\times B ]</p><p>where (L) is the number of layers, (S) is sequence length, (H_{kv}) is the number of KV heads, (D_h) is head dimension, and (B) is bytes per element. The leading 2 represents keys and values. MLA, sliding-window, sparse, compressed, and hybrid-attention architectures require different models, but the operational lesson is the same: <strong>context length and concurrency turn KV memory into a first-class capacity resource</strong>.</p><p>Peak tokens per second alone hides the outcomes users feel. A production benchmark should report at least:</p><ul><li>p50, p95, and p99 time to first token (TTFT),</li><li>inter-token latency (ITL) or time per output token (TPOT),</li><li>end-to-end latency,</li><li>request and token throughput,</li><li>error, timeout, cancellation, and OOM rates,</li><li>cache-hit rate and KV-token utilization,</li><li>SLO-compliant <strong>goodput</strong>, not merely admitted load.</li></ul><p>One useful definition is:</p><p>[ Goodput = \\frac{#{requests\\ meeting\\ all\\ SLOs}}{measurement\\ interval} ]</p><p>An optimization that raises aggregate throughput while making p99 TTFT or TPOT unacceptable is not a production win.</p><hr><h2 id="_2-a-modern-sglang-deployment-is-a-locality-aware-pipeline" tabindex="-1">2. A modern SGLang deployment is a locality-aware pipeline <a class="header-anchor" href="#_2-a-modern-sglang-deployment-is-a-locality-aware-pipeline" aria-label="Permalink to &quot;2. A modern SGLang deployment is a locality-aware pipeline&quot;">​</a></h2><p>A useful conceptual architecture is:</p><p><img src="'+n+`" alt="SGLang locality-aware production serving pipeline"></p><p>There are three interacting control loops:</p><ol><li><strong>Locality loop</strong> — preserve and reuse KV state with RadixAttention, session awareness, hierarchical storage, and cache-aware routing.</li><li><strong>execution loop</strong> — overlap CPU and GPU work, batch requests, choose kernels, capture CUDA graphs, and optionally verify multiple drafted tokens at once.</li><li><strong>topology loop</strong> — select TP, replicated DP, data-parallel attention, EP, DCP, or prefill-decode separation according to the model and traffic.</li></ol><p>Many disappointing deployments tune only the second loop. They install a fast kernel, increase batch size, and then lose the gain through poor prompt canonicalization, round-robin routing, cache fragmentation, or an inappropriate parallelism topology.</p><hr><h2 id="_3-radixattention-makes-prompt-structure-an-infrastructure-concern" tabindex="-1">3. RadixAttention makes prompt structure an infrastructure concern <a class="header-anchor" href="#_3-radixattention-makes-prompt-structure-an-infrastructure-concern" aria-label="Permalink to &quot;3. RadixAttention makes prompt structure an infrastructure concern&quot;">​</a></h2><p>RadixAttention stores reusable token prefixes and their KV tensors in a radix tree. When a new request arrives, SGLang can match the longest cached prefix, reuse the corresponding KV state, and compute only the uncached suffix. The runtime manages prefix search, insertion, and eviction automatically.</p><p>The mechanism changes an application-level concern—how prompts are serialized—into a serving-system concern.</p><p>Two prompts that are semantically identical but tokenized differently do not share a cache entry. Common causes include:</p><ul><li>inconsistent whitespace or separators,</li><li>non-deterministic JSON key order in tool definitions,</li><li>timestamps or request IDs inserted near the beginning,</li><li>changing system-prompt versions without explicit versioning,</li><li>RAG passages ordered differently for equivalent results,</li><li>different chat templates or tokenizer revisions across replicas.</li></ul><h3 id="production-practice-make-reusable-prefixes-canonical" tabindex="-1">Production practice: make reusable prefixes canonical <a class="header-anchor" href="#production-practice-make-reusable-prefixes-canonical" aria-label="Permalink to &quot;Production practice: make reusable prefixes canonical&quot;">​</a></h3><p>Place stable content first and volatile content late. Version system prompts deliberately. Serialize tools and schemas deterministically. Keep the model, tokenizer, chat template, and prompt-building library aligned across every worker expected to share traffic.</p><p>For shared-prefix workloads, use cache-aware routing rather than naive round robin. The gateway can route a request toward the worker with the most promising prefix locality while accounting for worker load. The original SGLang v0.4 measurements showed large gains on a deliberately prefix-heavy workload, but the exact multiplier is workload-specific; the durable lesson is that <strong>routing policy and cache policy must be designed together</strong>.</p><p>For long-lived agents and multi-turn conversations, current SGLang also provides session-aware radix caching. A stable <code>session_id</code> gives active-session KV soft eviction priority. It does not reconstruct the conversation or pin memory permanently: the application must still send the intended full prompt, and referenced KV can still be evicted under pressure. Close the session on normal completion, error, and cancellation paths so stale references do not distort eviction decisions.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:30000/close_session</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;session_id&quot;:&quot;agent-42&quot;}&#39;</span></span></code></pre></div><p>The central principle is:</p><blockquote><p>Cache-hit rate is not merely an engine property. It is a contract among prompt construction, routing, session lifecycle, and cache capacity.</p></blockquote><hr><h2 id="_4-build-a-boring-baseline-before-enabling-advanced-features" tabindex="-1">4. Build a boring baseline before enabling advanced features <a class="header-anchor" href="#_4-build-a-boring-baseline-before-enabling-advanced-features" aria-label="Permalink to &quot;4. Build a boring baseline before enabling advanced features&quot;">​</a></h2><p>Do not begin with speculative decoding, HiCache L3, PD disaggregation, and expert parallelism enabled together. That produces an impressive command line and an un-debuggable system.</p><p>Start with the smallest topology that fits the model and exposes metrics:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.launch_server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-metrics</span></span></code></pre></div><p>Pin the experimental envelope:</p><ul><li>SGLang release and container digest,</li><li>model and tokenizer revisions,</li><li>chat template,</li><li>dtype and quantization format,</li><li>GPU type, interconnect, driver, and runtime,</li><li>request dataset and random seed,</li><li>input/output-length distributions,</li><li>arrival-rate and concurrency model.</li></ul><p>Then validate correctness, warm-up behavior, steady-state latency, memory headroom, cancellation, shutdown, and restart. Only one major optimization should change per experiment.</p><h3 id="a-practical-tuning-loop" tabindex="-1">A practical tuning loop <a class="header-anchor" href="#a-practical-tuning-loop" aria-label="Permalink to &quot;A practical tuning loop&quot;">​</a></h3><p>SGLang&#39;s tuning guide exposes useful scheduler and memory signals. Treat its numerical suggestions as starting points rather than universal constants.</p><table tabindex="0"><thead><tr><th>Observed signal</th><th>Likely interpretation</th><th>First experiment</th><th>Main trade-off</th></tr></thead><tbody><tr><td>Queue repeatedly falls to zero during an intended saturation test</td><td>The client is not submitting fast enough</td><td>Increase client concurrency or submission rate</td><td>May stop representing real traffic</td></tr><tr><td>Queue is non-empty but KV token usage remains low</td><td>Admission is too conservative for actual completion behavior</td><td>Reduce <code>--schedule-conservativeness</code> gradually</td><td>Higher risk of request retraction</td></tr><tr><td>Frequent “KV cache pool is full; retract requests” warnings</td><td>Admission is too aggressive</td><td>Increase <code>--schedule-conservativeness</code></td><td>Lower peak concurrency</td></tr><tr><td>Large unused GPU-memory headroom after startup</td><td>KV pool may be undersized</td><td>Raise <code>--mem-fraction-static</code> in small increments</td><td>Less activation/CUDA-graph headroom</td></tr><tr><td>OOM during long-prompt prefill</td><td>Prefill activation working set is too large</td><td>Reduce <code>--chunked-prefill-size</code></td><td>Longer prefill time</td></tr><tr><td>OOM during decode</td><td>Too many active sequences or excessive KV pressure</td><td>Reduce <code>--max-running-requests</code></td><td>Lower concurrency</td></tr><tr><td>Decode remains launch/host-overhead sensitive</td><td>Graph capture range may be too narrow</td><td>Test <code>--cuda-graph-max-bs-decode</code></td><td>More reserved memory and startup work</td></tr></tbody></table><p>SGLang defines the high-level memory budget as:</p><p>[ GPU\\ memory \\approx weights + KV\\ pool + CUDA\\ graph\\ buffers + activations ]</p><p>and:</p><p>[ mem_fraction_static = \\frac{weights + KV\\ pool}{GPU\\ capacity} ]</p><p>The documentation suggests checking startup-reported free memory and often retaining roughly 5–8 GB for activations and graph buffers. This is a rule of thumb, not an SLO: multimodal encoders, very large prefill chunks, speculative draft states, unusual kernels, and model-specific workspaces can require a different reserve.</p><p>Tune memory under the worst legitimate request shape, not the median request.</p><hr><h2 id="_5-benchmark-the-workload-you-actually-operate" tabindex="-1">5. Benchmark the workload you actually operate <a class="header-anchor" href="#_5-benchmark-the-workload-you-actually-operate" aria-label="Permalink to &quot;5. Benchmark the workload you actually operate&quot;">​</a></h2><p>SGLang includes <code>bench_serving</code>, which can measure TTFT, ITL, TPOT, end-to-end latency, throughput, and speculative acceptance. It supports synthetic inputs and datasets for chat, generated shared prefixes, multimodal requests, speculative decoding, and multi-turn agentic traces.</p><p>A representative online test may look like:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.bench_serving</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dataset-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> random</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --random-input-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --random-output-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --num-prompts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --request-rate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --warmup-requests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> results.jsonl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-details</span></span></code></pre></div><p>Run a matrix rather than a single benchmark:</p><table tabindex="0"><thead><tr><th>Workload class</th><th>What it exposes</th></tr></thead><tbody><tr><td>Short interactive chat</td><td>CPU overhead, small-batch decode latency, streaming path</td></tr><tr><td>Long-context RAG</td><td>prefill throughput, chunking, TTFT, KV capacity</td></tr><tr><td>Repeated system/tool prefix</td><td>RadixAttention and cache-aware routing value</td></tr><tr><td>Multi-turn agent trace</td><td>session locality, cache eviction, variable acceptance, cancellation</td></tr><tr><td>Offline batch</td><td>maximum batch efficiency and aggregate throughput</td></tr><tr><td>Multimodal input</td><td>encoder memory, vision-token accounting, graph compatibility</td></tr></tbody></table><p>For each class, test:</p><ul><li>cold cache and warm cache,</li><li>steady open-loop arrivals and bursts,</li><li>realistic and adversarial length distributions,</li><li>low, medium, and saturation concurrency,</li><li>worker restart and cache loss,</li><li>timeout and cancellation storms.</li></ul><p>A closed-loop client that waits for each response before sending the next can hide queue collapse and coordinated omission. For online capacity work, an open-loop arrival process is usually more revealing. SGLang&#39;s non-infinite <code>--request-rate</code> models arrivals with a Poisson process; use a separate burst test for synchronized spikes.</p><hr><h2 id="_6-choose-parallelism-from-the-model-architecture-outward" tabindex="-1">6. Choose parallelism from the model architecture outward <a class="header-anchor" href="#_6-choose-parallelism-from-the-model-architecture-outward" aria-label="Permalink to &quot;6. Choose parallelism from the model architecture outward&quot;">​</a></h2><p>There is no universally best parallelism mode.</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Use it when</th><th>What it solves</th><th>Main cost or constraint</th></tr></thead><tbody><tr><td><strong>Tensor Parallelism (TP)</strong></td><td>A dense model does not fit, or a single replica needs multiple GPUs</td><td>Shards weights and compute within a request</td><td>Collective communication on the critical path</td></tr><tr><td><strong>Replicated DP through Model Gateway</strong></td><td>One replica fits and throughput needs horizontal scale</td><td>Independent request processing and failure domains</td><td>Duplicate weights; cache locality must be routed</td></tr><tr><td><strong>Data-Parallel Attention (DPA)</strong></td><td>MLA or supported attention layouts make TP duplicate KV state</td><td>Reduces per-rank KV duplication and permits larger batches</td><td>Topology constraints and redistribution around non-attention layers</td></tr><tr><td><strong>Expert Parallelism (EP)</strong></td><td>Large MoE expert weights or routed compute need sharding</td><td>Distributes experts and grouped GEMMs</td><td>All-to-all traffic and expert imbalance</td></tr><tr><td><strong>Decode Context Parallelism (DCP)</strong></td><td>Very long-context MLA decode is KV-capacity constrained</td><td>Stripes one request&#39;s MLA KV across ranks</td><td>Context-independent collectives; narrow compatibility envelope</td></tr><tr><td><strong>Prefill-Decode disaggregation (PD)</strong></td><td>Prefill interferes with decode, and phase demand can be scaled independently</td><td>Isolates compute-heavy and memory-heavy phases</td><td>KV transfer, more failure modes, more routing/state coordination</td></tr></tbody></table><h3 id="prefer-gateway-based-replicated-dp-when-a-replica-fits" tabindex="-1">Prefer gateway-based replicated DP when a replica fits <a class="header-anchor" href="#prefer-gateway-based-replicated-dp-when-a-replica-fits" aria-label="Permalink to &quot;Prefer gateway-based replicated DP when a replica fits&quot;">​</a></h3><p>For ordinary dense or GQA models, horizontally replicated workers behind the SGLang Model Gateway are often the cleanest first scale-out step. Current SGLang documentation explicitly discourages treating native in-process DP as the production routing layer; the gateway adds cache-aware policies, health checks, circuit breakers, rate limiting, queuing, observability, and dynamic worker management.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Workers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.launch_server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-metrics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Gateway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang_router.launch_router</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --worker-urls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://worker1:8000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://worker2:8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache_aware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span></span></code></pre></div><p>Use cache-aware routing when prefixes are valuable. Use a load-oriented policy such as power-of-two when load balance dominates and cache affinity is weak. Keep round robin as a diagnostic baseline, not an assumed optimum.</p><h3 id="use-dpa-for-the-architecture-it-was-designed-to-help" tabindex="-1">Use DPA for the architecture it was designed to help <a class="header-anchor" href="#use-dpa-for-the-architecture-it-was-designed-to-help" aria-label="Permalink to &quot;Use DPA for the architecture it was designed to help&quot;">​</a></h3><p>DPA is especially valuable for MLA-family models, where conventional TP can replicate a small or shared latent KV representation across ranks. Each attention-DP replica handles separate requests and its own KV cache; other layers can still use suitable model-parallel communication. Do not cargo-cult DPA onto a standard Llama deployment without measuring it.</p><h3 id="use-ep-when-the-model-is-actually-moe-bound" tabindex="-1">Use EP when the model is actually MoE-bound <a class="header-anchor" href="#use-ep-when-the-model-is-actually-moe-bound" aria-label="Permalink to &quot;Use EP when the model is actually MoE-bound&quot;">​</a></h3><p>For MoE models, SGLang separates the all-to-all communication backend from the expert-compute backend. Keep the compute backend on <code>auto</code> first. Select the communication backend according to hardware and fabric: DeepEP and related NVIDIA paths, MORI for AMD deployments, or another documented backend that matches the topology.</p><p>For DeepEP-style operation, <code>--deepep-mode auto</code> lets the runtime select throughput-oriented behavior for prefill and low-latency behavior for decode. Introduce Two-Batch Overlap and Expert Parallel Load Balancing only after profiles show communication bubbles or expert skew. At scale, EP performance is as much a network and load-balancing problem as a GEMM problem.</p><h3 id="treat-dcp-as-an-advanced-mla-long-context-tool" tabindex="-1">Treat DCP as an advanced MLA long-context tool <a class="header-anchor" href="#treat-dcp-as-an-advanced-mla-long-context-tool" aria-label="Permalink to &quot;Treat DCP as an advanced MLA long-context tool&quot;">​</a></h3><p>DCP stripes an MLA request&#39;s KV state by token position across ranks and merges partial attention outputs with an exact log-sum-exp reduction. It complements TP and DPA rather than replacing them.</p><p>Its topology must be validated explicitly. In a DPA composition:</p><p>[ attention_tp_size = \\frac{tp_size}{attention_dp_size} ]</p><p>and:</p><p>[ attention_tp_size \\bmod dcp_size = 0 ]</p><p>The current documentation warns that startup validation may check only a weaker divisibility condition, so the deployment layer should enforce the stronger containment rule itself. DCP also has combination-specific limitations with PD, HiCache, and speculative decoding. It belongs near the end of the adoption ladder, not the beginning.</p><hr><h2 id="_7-speculative-decoding-is-an-acceptance-rate-optimization" tabindex="-1">7. Speculative decoding is an acceptance-rate optimization <a class="header-anchor" href="#_7-speculative-decoding-is-an-acceptance-rate-optimization" aria-label="Permalink to &quot;7. Speculative decoding is an acceptance-rate optimization&quot;">​</a></h2><p>Speculative decoding uses a cheaper draft path to propose multiple tokens, then verifies them with the target model. The benefit depends on three quantities:</p><p>[ Gain \\approx verified\\ tokens\\ saved - draft\\ cost - verification\\ overhead ]</p><p>A high nominal draft length does not guarantee a speedup. At high batch sizes, rejected draft work is multiplied across many sequences, and an aggressive setting can reduce goodput.</p><p>Current SGLang supports multiple paths, including EAGLE-2, EAGLE-3, model-provided multi-token prediction (MTP), DFlash, a standalone smaller draft model, and an N-gram variant. The documentation positions EAGLE-3 as the preferred speed/quality path when a compatible draft model is available and EAGLE-2 as a broad default. Use MTP when the target model exposes suitable prediction heads. N-gram drafting can be useful when no extra model is available, but its support and compatibility differ from the EAGLE path.</p><p>A minimal EAGLE-3 experiment is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.launch_server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TARGET_MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --speculative-algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EAGLE3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --speculative-draft-model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DRAFT_MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-metrics</span></span></code></pre></div><p>Current SGLang uses the V2 speculative workers with the overlap scheduler enabled by default. When that path is intended, set <code>--speculative-eagle-topk 1</code> explicitly. A value greater than one is incompatible, and omitting the flag can allow model-specific auto-tuning to choose an incompatible branching factor. Use <code>--disable-overlap-schedule</code> only as a controlled synchronous baseline or debugging fallback.</p><p>Do not copy a reported tokens-per-second number into a capacity plan. Re-run the exact target/draft pair against your output-entropy and batch-size distribution. Compare:</p><ul><li>accepted draft length,</li><li>draft and verify time,</li><li>TPOT and ITL,</li><li>TTFT,</li><li>maximum concurrency,</li><li>additional model and CUDA-graph memory,</li><li>p99 goodput under the same arrival process.</li></ul><p>SGLang&#39;s adaptive speculative mode can change the speculative step count according to recent acceptance behavior and batch-size tier. It is useful for traffic that moves between high- and low-acceptance phases. The current implementation is limited to EAGLE/EAGLE-3 with top-k 1. At high batch sizes, narrow candidate ladders are often safer because wasted drafting becomes expensive. If one static configuration is already stable and well tuned, adaptive mode may add little.</p><p>The production rule is simple:</p><blockquote><p>Enable speculative decoding because measured acceptance amortizes its cost—not because a model family is listed as supported.</p></blockquote><hr><h2 id="_8-hicache-extends-reuse-beyond-hbm-but-capacity-is-not-locality" tabindex="-1">8. HiCache extends reuse beyond HBM, but capacity is not locality <a class="header-anchor" href="#_8-hicache-extends-reuse-beyond-hbm-but-capacity-is-not-locality" aria-label="Permalink to &quot;8. HiCache extends reuse beyond HBM, but capacity is not locality&quot;">​</a></h2><p>RadixAttention&#39;s fastest tier is GPU-resident KV. Long contexts and many sessions can evict useful prefixes even when the same data may soon be reused. HiCache extends the hierarchy:</p><ul><li><strong>L1:</strong> GPU KV cache,</li><li><strong>L2:</strong> host-memory KV cache private to one SGLang instance,</li><li><strong>L3:</strong> optional external storage that can be shared across instances when configured with a common namespace.</li></ul><p>An important scope detail is easy to miss: L1 and L2 are instance-private. Increasing the host-cache ratio does not create a node-wide or cluster-wide pool. Cross-instance reuse requires an L3 backend such as a supported Mooncake, HF3FS, NIXL, or AIBrix configuration. A local file backend remains node-local unless backed by a genuinely shared namespace.</p><p>A sensible adoption sequence is:</p><ol><li>Measure L1 hit rate, eviction, and recompute cost.</li><li>Add L2 when useful KV is evicted from HBM but host bandwidth and capacity can recover it profitably.</li><li>Add L3 only when cross-replica or cross-host reuse is significant enough to justify storage, metadata, and transfer complexity.</li></ol><p>The core flags look like:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang.launch_server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --page-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-hierarchical-cache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --hicache-ratio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --hicache-mem-layout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> page_first</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --hicache-io-backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kernel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --hicache-write-policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write_through</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --enable-metrics</span></span></code></pre></div><p>Choose prefetch policy according to the SLO:</p><ul><li><code>best_effort</code> favors latency predictability and abandons prefetch when needed,</li><li><code>wait_complete</code> favors maximum reuse but can add waiting time,</li><li><code>timeout</code> places an explicit bound between those behaviors.</li></ul><p>Before sharing L3 across fleets, make the cache namespace encode every compatibility dimension that affects KV meaning: model revision, tokenizer and template, KV dtype, attention layout, TP layout, page layout, and relevant runtime format. A cache hit on semantically incompatible state is worse than a miss.</p><p>HiCache also composes with PD deployments. A conservative pattern enables shared caching only on prefill nodes. A more advanced pattern asynchronously offloads decode KV so later turns can be recovered by prefill. The second design can help multi-turn traffic, but it adds write bandwidth and lifecycle complexity; validate it with actual session-return intervals.</p><hr><h2 id="_9-pd-disaggregation-is-phase-isolation-not-a-free-speedup" tabindex="-1">9. PD disaggregation is phase isolation, not a free speedup <a class="header-anchor" href="#_9-pd-disaggregation-is-phase-isolation-not-a-free-speedup" aria-label="Permalink to &quot;9. PD disaggregation is phase isolation, not a free speedup&quot;">​</a></h2><p>In a colocated engine, long prefill work can interrupt or distort decode scheduling. The effect appears as TTFT spikes, TPOT or ITL degradation, and uneven attention-DP progress. PD disaggregation assigns prefill and decode to separate worker pools and transfers the generated KV state between them.</p><p><img src="`+r+`" alt="Prefill-decode disaggregation request and KV-transfer flow"></p><p>SGLang supports Mooncake and NIXL transfer paths. On appropriate systems, KV traffic can use NVLink or RDMA. That does not eliminate the cost; it changes it from recomputation and phase interference into transfer, registration, queueing, and failure-recovery overhead.</p><p>Adopt PD only after answering four questions:</p><ol><li><strong>Interference:</strong> Do long prefills measurably harm decode p95/p99 latency in the colocated baseline?</li><li><strong>Demand ratio:</strong> Does the required prefill capacity scale differently from decode capacity over time?</li><li><strong>Transfer budget:</strong> Is KV transfer plus bootstrap delay smaller and more predictable than the interference being removed?</li><li><strong>Operational budget:</strong> Can the platform monitor and recover from partial handoffs, worker loss, stale registrations, timeout, and backpressure?</li></ol><p>At the gateway, a useful starting policy is cache-aware routing for prefill and load-oriented power-of-two routing for decode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang_router.launch_router</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --pd-disaggregation</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --prefill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://prefill1:30001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --decode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://decode1:30011</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --prefill-policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache_aware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --decode-policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> power_of_two</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span></span></code></pre></div><p>Profile the two phases separately. Track at least prefill compute time, decode TPOT, KV bytes, transfer duration, wait duration, timeout, failed handoff, and pool-specific queue depth.</p><p>Heterogeneous prefill and decode TP can be valuable when the phases prefer different shapes. It also changes the KV layout. Current SGLang provides a staging-buffer path for supported non-MLA cases, but this is an optimization to validate on a compatible model and topology—not a default design assumption.</p><hr><h2 id="_10-the-model-gateway-is-part-of-the-inference-runtime" tabindex="-1">10. The Model Gateway is part of the inference runtime <a class="header-anchor" href="#_10-the-model-gateway-is-part-of-the-inference-runtime" aria-label="Permalink to &quot;10. The Model Gateway is part of the inference runtime&quot;">​</a></h2><p>Treating the gateway as a generic HTTP load balancer throws away information the serving system needs.</p><p>The SGLang Model Gateway is designed to manage regular, prefill, and decode workers; route with cache and load awareness; expose OpenAI-compatible and native paths; and add retries, circuit breakers, rate limiting, health checks, metrics, and tracing. It can also coordinate multi-model and Kubernetes-discovered fleets.</p><p>Production guidance:</p><ul><li>Put admission control at the gateway before GPU queues become unbounded.</li><li>Bound retries. After a streaming response has emitted tokens, blind replay can duplicate output or tool actions; retry only within a deliberately idempotent protocol.</li><li>Use circuit breakers and readiness that reflect real inference health, not merely an open TCP port.</li><li>Propagate request IDs through gateway, worker, and PD transfer traces.</li><li>Secure client and worker paths separately; use TLS/mTLS where the threat model requires it.</li><li>Test cache locality under gateway high availability. Multiple gateway replicas may observe different routing histories, so HA can dilute cache-aware decisions unless traffic partitioning and state assumptions are explicit.</li></ul><p>The correct abstraction is not “load balancer in front of inference.” It is <strong>the distributed scheduler&#39;s control plane</strong>.</p><hr><h2 id="_11-use-breakable-cuda-graph-as-a-targeted-escape-hatch" tabindex="-1">11. Use Breakable CUDA Graph as a targeted escape hatch <a class="header-anchor" href="#_11-use-breakable-cuda-graph-as-a-targeted-escape-hatch" aria-label="Permalink to &quot;11. Use Breakable CUDA Graph as a targeted escape hatch&quot;">​</a></h2><p>Standard CUDA Graph capture removes repeated launch overhead, but a monolithic graph is difficult to inspect and cannot contain every dynamic operation. The blunt workaround—disabling graphs for the entire forward pass—can surrender performance far beyond the incompatible operation.</p><p>SGLang&#39;s Breakable CUDA Graph can split the forward pass into captured segments with selected eager execution between them. This is mainly a model- and backend-development technique, not a flag to enable on every production server.</p><p>For debugging, <code>--debug-cuda-graph</code> sends the decode forward path through eager execution while retaining the graph capture/replay control path. It intentionally removes the graph&#39;s performance benefit. For a production integration that has a small number of known non-capturable operations, set:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SGLANG_USE_BREAKABLE_CUDA_GRAPH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>and mark only the relevant functions with SGLang&#39;s eager-on-graph mechanism. Each break adds another graph launch and eager call, so profile the segmented path against both the full graph and fully eager baselines. The current implementation supports CUDA and ROCm/HIP, and it is not compatible with SGLang&#39;s memory-saver CUDA-graph mode.</p><p>The operational rule is:</p><blockquote><p>Break the graph at the smallest incompatible boundary; do not turn a local dynamic operation into a global eager-mode regression.</p></blockquote><hr><h2 id="_12-observability-should-explain-the-bottleneck-not-only-report-latency" tabindex="-1">12. Observability should explain the bottleneck, not only report latency <a class="header-anchor" href="#_12-observability-should-explain-the-bottleneck-not-only-report-latency" aria-label="Permalink to &quot;12. Observability should explain the bottleneck, not only report latency&quot;">​</a></h2><p>Enable worker metrics with <code>--enable-metrics</code> and scrape <code>/metrics</code>. SGLang exposes counters and histograms for prompt and generated tokens, TTFT, TPOT, end-to-end latency, queue depth, running requests, token usage, throughput, cache hit rate, and speculative state, among other signals. The Model Gateway adds its own routing and reliability metrics plus OpenTelemetry integration.</p><p>A minimal dashboard should connect causes to outcomes:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Key signals</th><th>Question answered</th></tr></thead><tbody><tr><td>Client/Gateway</td><td>admitted RPS, rejected RPS, queue delay, rate-limit, route policy, retries, breaker state</td><td>Is demand being controlled and routed correctly?</td></tr><tr><td>User SLO</td><td>TTFT, TPOT/ITL, end-to-end p50/p95/p99, stream errors</td><td>What does the user experience?</td></tr><tr><td>Scheduler</td><td>waiting/running requests, token usage, retractions, batch size, graph use</td><td>Is batching efficient and safe?</td></tr><tr><td>KV locality</td><td>prefix hit rate, reused tokens, eviction, HiCache H2D/D2H/L3 latency</td><td>Is cache capacity producing real reuse?</td></tr><tr><td>Speculation</td><td>active steps, draft tokens, accepted length, verify cost</td><td>Does drafting pay for itself?</td></tr><tr><td>PD</td><td>prefill/decode queues, handoff time, transfer bytes, timeout/failure</td><td>Does phase separation remove more interference than it adds?</td></tr><tr><td>GPU/fabric</td><td>utilization, HBM use/bandwidth, collectives, RDMA/NVLink throughput, errors</td><td>Is the bottleneck compute, memory, or communication?</td></tr><tr><td>Capacity</td><td>goodput per GPU, tok/s per GPU, cost per SLO-compliant request</td><td>Is the system economically efficient?</td></tr></tbody></table><p>SGLang does not log request content by default. Keep that default unless there is a clear debugging and privacy policy. Request dump/replay and crash dumps are powerful for reproducing failures, but they may contain prompts, generated text, tool payloads, or other sensitive data. Encrypt, restrict, expire, and audit those artifacts like production data.</p><hr><h2 id="_13-upgrade-and-startup-behavior-are-part-of-reliability" tabindex="-1">13. Upgrade and startup behavior are part of reliability <a class="header-anchor" href="#_13-upgrade-and-startup-behavior-are-part-of-reliability" aria-label="Permalink to &quot;13. Upgrade and startup behavior are part of reliability&quot;">​</a></h2><p>SGLang evolves quickly. Version-specific performance claims should be treated as release benchmarks, not timeless defaults.</p><p>As of August 30, 2026, the latest stable release is v0.5.18. Notable operational changes include:</p><ul><li>an opt-in overlapped checkpoint-staging mode, <code>--startup-weight-load-mode overlap</code>, which overlaps storage staging with CUDA-graph capture,</li><li>a unified <code>SGLANG_CACHE_DIR</code> for Triton, FlashInfer, Inductor, DeepGEMM, and CUDA-driver compilation caches,</li><li>release-specific kernel and communication improvements for newer NVIDIA and AMD architectures.</li></ul><p>The first startup after an upgrade may recompile caches. Do not let that first request define pod readiness.</p><p>A safer rollout sequence is:</p><ol><li>Pin the release, image digest, model revision, and launch arguments.</li><li>Start a canary on the exact production GPU and fabric.</li><li>Load weights, compile kernels, and capture graphs before declaring readiness.</li><li>Run correctness and representative warm/cold benchmarks.</li><li>Compare SLO goodput, memory, cache behavior, and error rates—not only average tokens per second.</li><li>Preserve the previous image and cache assumptions for rollback.</li></ol><p>For large TP deployments, investigate pre-sharded checkpoint formats, layered loading, streaming loaders, or remote-instance loading only after storage traces identify startup I/O as the bottleneck.</p><hr><h2 id="_14-a-practical-adoption-ladder" tabindex="-1">14. A practical adoption ladder <a class="header-anchor" href="#_14-a-practical-adoption-ladder" aria-label="Permalink to &quot;14. A practical adoption ladder&quot;">​</a></h2><p><img src="`+o+'" alt="A staged path from a correct baseline to topology specialization"></p><h3 id="stage-0-—-correct-single-worker-baseline" tabindex="-1">Stage 0 — Correct single-worker baseline <a class="header-anchor" href="#stage-0-—-correct-single-worker-baseline" aria-label="Permalink to &quot;Stage 0 — Correct single-worker baseline&quot;">​</a></h3><ul><li>One worker or the smallest TP that fits.</li><li>OpenAI-compatible correctness tests.</li><li>Metrics, representative benchmark, memory/OOM envelope.</li><li>Pinned software, model, template, and hardware.</li></ul><h3 id="stage-1-—-exploit-locality-and-horizontal-scale" tabindex="-1">Stage 1 — Exploit locality and horizontal scale <a class="header-anchor" href="#stage-1-—-exploit-locality-and-horizontal-scale" aria-label="Permalink to &quot;Stage 1 — Exploit locality and horizontal scale&quot;">​</a></h3><ul><li>Canonicalize reusable prefixes.</li><li>Add SGLang Model Gateway.</li><li>Compare round-robin, load-oriented, and cache-aware routing.</li><li>Add session-aware cache for real multi-turn workloads.</li></ul><h3 id="stage-2-—-add-measured-acceleration" tabindex="-1">Stage 2 — Add measured acceleration <a class="header-anchor" href="#stage-2-—-add-measured-acceleration" aria-label="Permalink to &quot;Stage 2 — Add measured acceleration&quot;">​</a></h3><ul><li>Tune memory fraction, chunked prefill, admission, and graph range.</li><li>Test EAGLE/MTP speculative decoding with acceptance metrics.</li><li>Add HiCache L2 when GPU eviction destroys valuable reuse.</li><li>Add L3 only for demonstrated cross-instance reuse.</li></ul><h3 id="stage-3-—-specialize-the-topology" tabindex="-1">Stage 3 — Specialize the topology <a class="header-anchor" href="#stage-3-—-specialize-the-topology" aria-label="Permalink to &quot;Stage 3 — Specialize the topology&quot;">​</a></h3><ul><li>DPA for supported MLA-style attention.</li><li>EP for large MoE models with a fabric-appropriate all-to-all backend.</li><li>PD when phase interference and independent scaling justify KV transfer.</li><li>DCP for long-context MLA capacity after validating composition constraints.</li></ul><p>At every stage, retain the previous stage as a benchmarkable rollback topology.</p><hr><h2 id="_15-production-checklist" tabindex="-1">15. Production checklist <a class="header-anchor" href="#_15-production-checklist" aria-label="Permalink to &quot;15. Production checklist&quot;">​</a></h2><p>Before calling the deployment production-ready, verify that:</p><ul><li>the benchmark reproduces real prompt, output, prefix, and arrival distributions;</li><li>TTFT, TPOT/ITL, end-to-end latency, and goodput have explicit SLOs;</li><li>prompts, tools, templates, tokenizer, and model revisions are canonical and pinned;</li><li>cache-aware routing is justified by measured prefix reuse;</li><li>memory tuning survives worst-case input, concurrency, and multimodal shapes;</li><li>speculative decoding improves goodput at real batch sizes and output entropy;</li><li>PD transfer latency and failure recovery are observable and bounded;</li><li>EP expert imbalance and all-to-all traffic are monitored;</li><li>gateway admission, retries, circuit breaking, and cancellation semantics are tested;</li><li>request dumps, crash dumps, traces, and logs follow the data-security policy;</li><li>upgrades precompile/warm before readiness and have a tested rollback path.</li></ul><hr><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The enduring insight in SGLang is not one kernel or one benchmark. It is the co-design of execution and reuse.</p><p>RadixAttention turns token-prefix structure into reusable compute. The overlapped scheduler hides host work. Speculative decoding trades cheap guesses for fewer target-model steps. HiCache extends useful state beyond GPU memory. The Model Gateway preserves locality while controlling distributed load. PD, DPA, EP, and DCP specialize execution around phase and model architecture.</p><p>That power also makes configuration-by-checklist dangerous. Each feature moves cost rather than deleting it:</p><ul><li>caching trades memory and state management for recomputation,</li><li>speculation trades draft and verification work for fewer decode rounds,</li><li>PD trades phase interference for KV transfer and distributed coordination,</li><li>EP trades replicated experts for all-to-all communication,</li><li>DCP trades replicated long-context KV for per-layer collectives.</li></ul><p>The production method is therefore incremental:</p><blockquote><p>Establish a correct baseline, measure the dominant bottleneck, introduce the smallest mechanism that targets it, and keep the optimization only when it improves SLO-compliant goodput under realistic traffic.</p></blockquote><p>That is the most useful way to understand SGLang in 2026: not merely as a fast model server, but as a toolkit for building a locality-aware, phase-aware, model-aware inference system.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Lianmin Zheng et al., <a href="https://arxiv.org/abs/2312.07104" target="_blank" rel="noreferrer">SGLang: Efficient Execution of Structured Language Model Programs</a>, NeurIPS 2024.</li><li>LMSYS, <a href="https://www.lmsys.org/blog/2024-01-17-sglang/" target="_blank" rel="noreferrer">Fast and Expressive LLM Inference with RadixAttention and SGLang</a>, 2024.</li><li>LMSYS, <a href="https://www.lmsys.org/blog/2024-12-04-sglang-v0-4/" target="_blank" rel="noreferrer">SGLang v0.4: Zero-Overhead Batch Scheduler, Cache-Aware Load Balancer, Faster Structured Outputs</a>, 2024.</li><li>LMSYS, <a href="https://www.lmsys.org/blog/2025-05-05-large-scale-ep/" target="_blank" rel="noreferrer">Deploying DeepSeek with PD Disaggregation and Large-Scale Expert Parallelism on 96 H100 GPUs</a>, 2025.</li><li>AMD, <a href="https://www.amd.com/en/corporate/events/advancing-ai/2025/advancing-ai-2025.html" target="_blank" rel="noreferrer">Efficient LLM Inference with SGLang — Lianmin Zheng</a>, 2025.</li><li>YouTube, <a href="https://www.youtube.com/watch?v=G4ZeVP7n0Ik" target="_blank" rel="noreferrer">Efficient LLM Inference with SGLang</a>.</li><li>SGLang, <a href="https://github.com/sgl-project/sgl-learning-materials" target="_blank" rel="noreferrer">Learning Materials</a>.</li><li>SGLang, <a href="https://docs.sglang.io/" target="_blank" rel="noreferrer">Documentation</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/hyperparameter_tuning" target="_blank" rel="noreferrer">Hyperparameter Tuning</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/speculative_decoding" target="_blank" rel="noreferrer">Speculative Decoding</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/adaptive_speculative_decoding" target="_blank" rel="noreferrer">Adaptive Speculative Decoding</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/session_radix_cache" target="_blank" rel="noreferrer">Session-Aware Radix Cache</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/hicache_best_practices" target="_blank" rel="noreferrer">HiCache Best Practices</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/dp_dpa_smg_guide" target="_blank" rel="noreferrer">DP, DPA, and SGLang Model Gateway</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/expert_parallelism" target="_blank" rel="noreferrer">Expert Parallelism</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/dcp" target="_blank" rel="noreferrer">Decode Context Parallelism</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/pd_disaggregation" target="_blank" rel="noreferrer">PD Disaggregation</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/sgl_model_gateway" target="_blank" rel="noreferrer">SGLang Model Gateway</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/breakable_cuda_graph" target="_blank" rel="noreferrer">Breakable CUDA Graph</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/advanced_features/observability" target="_blank" rel="noreferrer">Observability and Production Metrics</a>.</li><li>SGLang, <a href="https://docs.sglang.io/docs/developer_guide/bench_serving" target="_blank" rel="noreferrer">Benchmark Serving Guide</a>.</li><li>SGLang, <a href="https://github.com/sgl-project/sglang/releases/tag/v0.5.18" target="_blank" rel="noreferrer">v0.5.18 Release Notes</a>, 2026.</li></ol>',195)])])}const y=a(l,[["render",d]]);export{m as __pageData,y as default};
